package com.bank.spark.service;

import com.bank.spark.model.Edge;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// GraphX-style connected components via union-find over transfer edges.
public class ConnectedComponents {

    private static final Logger log = Logger.getLogger(ConnectedComponents.class.getName());
    private final Map<String, String> parent = new HashMap<>();

    private String find(String x) {
        parent.putIfAbsent(x, x);
        while (!parent.get(x).equals(x)) {
            parent.put(x, parent.get(parent.get(x))); // path compression
            x = parent.get(x);
        }
        return x;
    }

    private void union(String a, String b) {
        parent.put(find(a), find(b));
    }

    // Label each account with its component id (the ring it belongs to).
    public Map<String, String> label(List<Edge> edges) {
        for (Edge e : edges) union(e.getSrc(), e.getDst());
        Map<String, String> labels = new HashMap<>();
        for (String v : parent.keySet()) labels.put(v, find(v));
        log.info(() -> "Connected components computed over " + edges.size() + " edges");
        return labels;
    }

    // Size of the component a given account belongs to.
    public long componentSize(Map<String, String> labels, String account) {
        String comp = labels.get(account);
        return labels.values().stream().filter(c -> c.equals(comp)).count();
    }
}
