package com.bank.spark.service;

import java.math.BigDecimal;
import java.util.logging.Logger;

// MLlib-style pipeline stand-in: assemble features → score fraud.
// Real code: Pipeline(StringIndexer, VectorAssembler, LogisticRegression).fit(train).
public class FraudPipeline {

    private static final Logger log = Logger.getLogger(FraudPipeline.class.getName());

    // Features: amount, channel risk, and the account's graph component size.
    public double score(BigDecimal amount, String channel, long componentSize) {
        double amountSignal = amount.compareTo(new BigDecimal("100000")) > 0 ? 0.4 : 0.0;
        double channelSignal = "UNKNOWN".equals(channel) ? 0.3 : 0.0;
        double graphSignal = componentSize >= 4 ? 0.4 : 0.0; // large ring → suspicious
        double score = Math.min(1.0, amountSignal + channelSignal + graphSignal);
        log.info(() -> "Fraud features [amt=" + amount + ", channel=" + channel
                + ", compSize=" + componentSize + "] → score " + score);
        return score;
    }
}
