package com.bank.spark;

import com.bank.spark.model.Edge;
import com.bank.spark.service.ConnectedComponents;
import com.bank.spark.service.FraudPipeline;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: GraphX-style components feed an MLlib-style fraud score.
public class GraphMlDemo {

    private static final Logger log = Logger.getLogger(GraphMlDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Transfer graph: a 4-account ring (A→B→C→D→A) plus an isolated pair.
        List<Edge> edges = List.of(
            new Edge("A", "B"), new Edge("B", "C"),
            new Edge("C", "D"), new Edge("D", "A"),
            new Edge("SAV2001", "CUR3001"));

        ConnectedComponents cc = new ConnectedComponents();
        Map<String, String> labels = cc.label(edges);
        long ringSize = cc.componentSize(labels, "A");
        long pairSize = cc.componentSize(labels, "SAV2001");
        log.info(() -> "Account A component size = " + ringSize + " (ring)");
        log.info(() -> "Account SAV2001 component size = " + pairSize + " (pair)");

        FraudPipeline pipeline = new FraudPipeline();
        // A high-value UNKNOWN-channel txn inside the 4-ring → high score.
        double s1 = pipeline.score(new BigDecimal("250000"), "UNKNOWN", ringSize);
        // A normal txn in the pair → low score.
        double s2 = pipeline.score(new BigDecimal("3000"), "UPI", pairSize);
        log.info(() -> "Ring txn fraud score=" + s1 + " ; pair txn fraud score=" + s2);

        log.info("GraphX + MLlib demo complete.");
    }
}
